"""Root current-rule corrections from full official/Waha audit E."""
import json,re
from pathlib import Path
R=Path(__file__).parent
def read(n):return json.loads((R/n).read_text(encoding='utf8'))
a=read('inventory/critic-full-team-audit-e.json');q=a['findings'];c=read('inventory/current-rule-base-cards.json');sources={x['team']:x for x in a['sources']};out=[]
def patch(n,id=None):
 x=q[n];id=id or x['exactID'];s=sources[x['team']]
 p={'id':id,'expectedTitle':c[id]['titleEnglish'],'team':x['team'],'source':{'officialPdf':s['officialPdfUrl'],'date':s['catalogDate'],'wahapedia':s['wahapediaPage'],'checkedOn':'2026-10-05',**x['officialEvidence']}};out.append(p);return p
def old(n,h=None):return next(b for b in c[q[n]['exactID']].get('blocks',[]) if h is None or b.get('headingEnglish')==h)
def body(n,ru,en,h=None):
 b=old(n,h);p=patch(n);u={'heading':b['headingEnglish'],'russian':ru,'english':en,'proseTitles':[b['headingEnglish'].split(' ·')[0].split(' (')[0].split(' —')[0].split(':')[0]]};p['blocks']=[u];return u
def edit(n,ro,rn,eo,en,h=None):
 b=old(n,h);assert ro in b['russian'] and eo in b['english'],(n,ro,eo)
 return body(n,b['russian'].replace(ro,rn),b['english'].replace(eo,en),h)
def extra(n,ru,en,h=None):
 b=old(n,h);return body(n,b['russian']+'\n'+ru,b['english']+' '+en,h)
def weapon(n,name,**values):patch(n)['weapons']=[{'name':name,**values}]
